#!/usr/bin/env python3
"""Grade the check-gate `cron` task: run the pristine visible tests plus
hidden tests derived from the task's specification against a copy of the
workspace whose own tests/ directory is replaced. Editing the workspace's tests
changes nothing here. The last output line is `<failed> failed, <passed> passed`."""
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

TEST_FILES = {'tests/__init__.py': '# Unit tests.\n', 'tests/run.py': '"""Run the unit tests under tests/ and report them like pytest\'s summary:\nthe failure details first, then one `FAILED <test> - <reason>` line per\nfailing test and a count line. Exit status 1 when anything failed."""\nimport os\nimport sys\nimport unittest\n\n\ndef main():\n    here = os.path.dirname(os.path.abspath(__file__))\n    root = os.path.dirname(here)\n    sys.path.insert(0, root)\n    suite = unittest.defaultTestLoader.discover(here, pattern="test_*.py", top_level_dir=root)\n    result = unittest.TestResult()\n    suite.run(result)\n    failed = result.failures + result.errors\n    for test, trace in failed:\n        print("_" * 12 + " " + test.id() + " " + "_" * 12)\n        print(trace.rstrip())\n        print()\n    failing_methods = set()\n    for test, trace in failed:\n        case = getattr(test, "test_case", test)\n        failing_methods.add(case.id())\n        parts = case.id().rsplit(".", 2)\n        if len(parts) == 3:\n            module, cls, method = parts\n            name = "%s.py::%s::%s" % (module.replace(".", "/"), cls, method)\n        else:\n            name = case.id()\n        if case is not test:\n            name += " " + test._subDescription()\n        lines = trace.strip().splitlines()\n        reason = lines[-1] if lines else ""\n        print("FAILED %s - %s" % (name, reason))\n    print("%d failed, %d passed" % (len(failing_methods), result.testsRun - len(failing_methods)))\n    return 1 if failed else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_basics.py': 'import datetime\nimport unittest\n\nfrom cronexpr import next_fire\n\nclass CronBasicsTest(unittest.TestCase):\n    def test_every_minute(self):\n        self.assertEqual(next_fire(\'* * * * *\', datetime.datetime(2026, 10, 8, 10, 0, 30)), datetime.datetime(2026, 10, 8, 10, 1))\n\n    def test_result_has_no_seconds(self):\n        self.assertEqual(next_fire(\'* * * * *\', datetime.datetime(2026, 10, 8, 10, 0, 59, 900000)), datetime.datetime(2026, 10, 8, 10, 1))\n\n    def test_strictly_after_a_match(self):\n        self.assertEqual(next_fire(\'30 9 * * *\', datetime.datetime(2026, 10, 8, 9, 30)), datetime.datetime(2026, 10, 9, 9, 30))\n\n    def test_later_today(self):\n        self.assertEqual(next_fire(\'30 9 * * *\', datetime.datetime(2026, 10, 8, 8)), datetime.datetime(2026, 10, 8, 9, 30))\n\n    def test_hourly_quarter(self):\n        self.assertEqual(next_fire(\'15 * * * *\', datetime.datetime(2026, 10, 8, 10, 20)), datetime.datetime(2026, 10, 8, 11, 15))\n\n    def test_list(self):\n        self.assertEqual(next_fire(\'0,30 * * * *\', datetime.datetime(2026, 10, 8, 10, 10)), datetime.datetime(2026, 10, 8, 10, 30))\n\n    def test_hour_range(self):\n        self.assertEqual(next_fire(\'0 9-17 * * *\', datetime.datetime(2026, 10, 8, 17, 30)), datetime.datetime(2026, 10, 9, 9, 0))\n\n    def test_star_step(self):\n        self.assertEqual(next_fire(\'*/15 * * * *\', datetime.datetime(2026, 10, 8, 10, 16)), datetime.datetime(2026, 10, 8, 10, 30))\n\n    def test_range_step(self):\n        self.assertEqual(next_fire(\'0 8-18/5 * * *\', datetime.datetime(2026, 10, 8, 13)), datetime.datetime(2026, 10, 8, 18, 0))\n\n    def test_value_step(self):\n        self.assertEqual(next_fire(\'5/20 * * * *\', datetime.datetime(2026, 10, 8, 10, 26)), datetime.datetime(2026, 10, 8, 10, 45))\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_calendar.py': 'import datetime\nimport unittest\n\nfrom cronexpr import next_fire\n\nclass CronCalendarTest(unittest.TestCase):\n    def test_month_names(self):\n        self.assertEqual(next_fire(\'0 0 1 JAN,jul *\', datetime.datetime(2026, 2, 1)), datetime.datetime(2026, 7, 1, 0, 0))\n\n    def test_weekday_range_names(self):\n        self.assertEqual(next_fire(\'0 9 * * mon-fri\', datetime.datetime(2026, 10, 9, 10)), datetime.datetime(2026, 10, 12, 9, 0))\n\n    def test_seven_is_sunday(self):\n        self.assertEqual(next_fire(\'0 12 * * 7\', datetime.datetime(2026, 10, 8)), datetime.datetime(2026, 10, 11, 12, 0))\n\n    def test_day_of_month_or_weekday(self):\n        self.assertEqual(next_fire(\'0 0 13 * FRI\', datetime.datetime(2026, 10, 10)), datetime.datetime(2026, 10, 13, 0, 0))\n\n    def test_star_step_day_of_month_and_weekday(self):\n        self.assertEqual(next_fire(\'0 0 */2 * MON\', datetime.datetime(2026, 10, 8)), datetime.datetime(2026, 10, 19, 0, 0))\n\n    def test_month_rollover(self):\n        self.assertEqual(next_fire(\'0 0 1 * *\', datetime.datetime(2026, 10, 31, 23, 59)), datetime.datetime(2026, 11, 1, 0, 0))\n\n    def test_year_rollover(self):\n        self.assertEqual(next_fire(\'0 0 1 1 *\', datetime.datetime(2026, 6, 1)), datetime.datetime(2027, 1, 1, 0, 0))\n\n    def test_leap_day(self):\n        self.assertEqual(next_fire(\'0 0 29 2 *\', datetime.datetime(2026, 3, 1)), datetime.datetime(2028, 2, 29, 0, 0))\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_macros.py': 'import datetime\nimport unittest\n\nfrom cronexpr import next_fire\n\nclass CronMacrosTest(unittest.TestCase):\n    def test_daily(self):\n        self.assertEqual(next_fire(\'@daily\', datetime.datetime(2026, 10, 8, 10)), datetime.datetime(2026, 10, 9, 0, 0))\n\n    def test_hourly(self):\n        self.assertEqual(next_fire(\'@hourly\', datetime.datetime(2026, 10, 8, 10)), datetime.datetime(2026, 10, 8, 11, 0))\n\n    def test_weekly_is_sunday_midnight(self):\n        self.assertEqual(next_fire(\'@weekly\', datetime.datetime(2026, 10, 8, 10)), datetime.datetime(2026, 10, 11, 0, 0))\n\n    def test_monthly(self):\n        self.assertEqual(next_fire(\'@monthly\', datetime.datetime(2026, 10, 8, 10)), datetime.datetime(2026, 11, 1, 0, 0))\n\n    def test_yearly(self):\n        self.assertEqual(next_fire(\'@yearly\', datetime.datetime(2026, 10, 8, 10)), datetime.datetime(2027, 1, 1, 0, 0))\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_errors.py': 'import datetime\nimport unittest\n\nfrom cronexpr import next_fire\n\nclass CronErrorsTest(unittest.TestCase):\n    def test_too_few_fields(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'* * * *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_too_many_fields(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'* * * * * *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_minute_out_of_range(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'60 * * * *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_hour_out_of_range(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'0 24 * * *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_day_zero(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'0 0 0 * *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_month_thirteen(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'0 0 1 13 *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_weekday_eight(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'0 0 * * 8\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_unknown_name(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'0 0 * FOO *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_reversed_range(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'5-1 * * * *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_zero_step(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'*/0 * * * *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_bad_step(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'*/x * * * *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_empty_item(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'1,,2 * * * *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_unknown_macro(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'@sometimes\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_never_fires(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'0 0 30 2 *\', datetime.datetime(2026, 10, 8, 10))\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_hidden_cron.py': 'import datetime\nimport unittest\n\nfrom cronexpr import next_fire\n\nclass CronHiddenTest(unittest.TestCase):\n    def test_tabs_and_spaces(self):\n        self.assertEqual(next_fire(\'0\\t9  * * *\', datetime.datetime(2026, 10, 8, 10)), datetime.datetime(2026, 10, 9, 9, 0))\n\n    def test_annually_and_midnight_a(self):\n        self.assertEqual(next_fire(\'@annually\', datetime.datetime(2026, 10, 8, 10)), datetime.datetime(2027, 1, 1, 0, 0))\n\n    def test_annually_and_midnight_b(self):\n        self.assertEqual(next_fire(\'@midnight\', datetime.datetime(2026, 10, 8, 10)), datetime.datetime(2026, 10, 9, 0, 0))\n\n    def test_thirty_first_skips_short_months(self):\n        self.assertEqual(next_fire(\'0 0 31 * *\', datetime.datetime(2026, 4, 1)), datetime.datetime(2026, 5, 31, 0, 0))\n\n    def test_thirty_first_in_short_months_never(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'0 0 31 4,6,9,11 *\', datetime.datetime(2026, 4, 1))\n\n    def test_or_rule_with_month(self):\n        self.assertEqual(next_fire(\'0 0 1 3 MON\', datetime.datetime(2026, 2, 15)), datetime.datetime(2026, 3, 1, 0, 0))\n\n    def test_or_rule_second_match(self):\n        self.assertEqual(next_fire(\'0 0 1 3 MON\', datetime.datetime(2026, 3, 1)), datetime.datetime(2026, 3, 2, 0, 0))\n\n    def test_weekday_range_to_seven(self):\n        self.assertEqual(next_fire(\'0 0 * * 5-7\', datetime.datetime(2026, 10, 7, 12)), datetime.datetime(2026, 10, 9, 0, 0))\n\n    def test_month_name_range_mixed_case(self):\n        self.assertEqual(next_fire(\'0 0 1 Jan-Mar *\', datetime.datetime(2026, 3, 2)), datetime.datetime(2027, 1, 1, 0, 0))\n\n    def test_zero_and_seven(self):\n        self.assertEqual(next_fire(\'0 0 * * 0,7\', datetime.datetime(2026, 10, 8)), datetime.datetime(2026, 10, 11, 0, 0))\n\n    def test_leap_day_after_leap_day(self):\n        self.assertEqual(next_fire(\'0 0 29 2 *\', datetime.datetime(2028, 2, 29)), datetime.datetime(2032, 2, 29, 0, 0))\n\n    def test_weekday_name_range_step(self):\n        self.assertEqual(next_fire(\'0 0 * * MON-FRI/2\', datetime.datetime(2026, 10, 8)), datetime.datetime(2026, 10, 9, 0, 0))\n\n    def test_hour_value_step(self):\n        self.assertEqual(next_fire(\'0 3/6 * * *\', datetime.datetime(2026, 10, 8, 10)), datetime.datetime(2026, 10, 8, 15, 0))\n\n    def test_january_monday_across_year(self):\n        self.assertEqual(next_fire(\'0 0 * 1 MON\', datetime.datetime(2026, 12, 31)), datetime.datetime(2027, 1, 4, 0, 0))\n\n    def test_dangling_range(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'1- * * * *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_missing_base(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'/5 * * * *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_weekday_name_in_month_field(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'0 0 1 MON *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_month_name_reversed(self):\n        with self.assertRaises(ValueError):\n            next_fire(\'0 0 1 DEC-JAN *\', datetime.datetime(2026, 10, 8, 10))\n\n    def test_dom_star_with_weekday_and(self):\n        self.assertEqual(next_fire(\'0 0 * * FRI\', datetime.datetime(2026, 10, 8)), datetime.datetime(2026, 10, 9, 0, 0))\n\n    def test_minute_list_and_range(self):\n        self.assertEqual(next_fire(\'0-2,58 * * * *\', datetime.datetime(2026, 10, 8, 10, 2)), datetime.datetime(2026, 10, 8, 10, 58))\n\n\nif __name__ == "__main__":\n    unittest.main()\n'}

SKIP = {"tests", ".git", ".home", "__pycache__", "events.jsonl"}


def main():
    workspace = Path(sys.argv[1]) if len(sys.argv) > 1 else Path.cwd()
    with tempfile.TemporaryDirectory() as tmp:
        root = Path(tmp) / "workspace"
        root.mkdir()
        for entry in workspace.iterdir():
            if entry.name in SKIP or entry.name.startswith(".") or entry.is_symlink():
                continue
            if entry.is_dir():
                shutil.copytree(entry, root / entry.name, symlinks=False,
                                ignore=shutil.ignore_patterns("__pycache__"))
            elif entry.is_file():
                shutil.copy2(entry, root / entry.name)
        for rel, text in TEST_FILES.items():
            target = root / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(text, encoding="utf-8")
        try:
            result = subprocess.run([sys.executable, "tests/run.py"], cwd=root, capture_output=True,
                                    text=True, timeout=90)
        except subprocess.TimeoutExpired:
            print("tests timed out")
            return 1
        output = result.stdout + result.stderr
        print(output[-4000:])
        return 0 if result.returncode == 0 else 1


if __name__ == "__main__":
    sys.exit(main())
